// GENERATED by builder application candidate v1; neutral opt-in local host behavior.
import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createServer,request} from 'node:http';
import {once} from 'node:events';
import {createLocalEntryHost} from './local-entry-host.mjs';
const input={scriptId:'public-config',publicConfig:{public:'</script><script>PRIVATE</script>\u2028'},apiOrigin:'http://127.0.0.1:8188',routes:['/api/v1/context']};
test('local host embeds bounded inert JSON without HTML termination and preserves other scripts',()=>{
 const host=createLocalEntryHost(input),plugin=host.plugins[0];const html='<script id="public-config" type="application/json">null</script><script type="module" src="/src/main.ts"></script>';
 const transformed=plugin.transformIndexHtml(html);assert.ok(!transformed.includes('</script><script>PRIVATE'));assert.ok(transformed.includes('src="/src/main.ts"'));const raw=transformed.match(/application\/json">(.*?)<\/script>/s)[1];assert.deepEqual(JSON.parse(raw),input.publicConfig);assert.throws(()=>plugin.transformIndexHtml(html+html),{message:'local_entry_host_invalid'});assert.throws(()=>plugin.transformIndexHtml(''),{message:'local_entry_host_invalid'});
 assert.equal(host.server.host,'127.0.0.1');assert.equal(host.envFile,false);assert.equal(host.publicDir,false);assert.equal(host.server.hmr,false);assert.equal(host.server.strictPort,true);
});
test('local host rejects remote/ambiguous upstreams, unsafe routes, oversized public input and invalid scripts',()=>{
 for(const apiOrigin of ['http://localhost:8188','https://127.0.0.1:8188','http://127.0.0.2:8188','http://127.0.0.1:0','http://127.0.0.1:8188/path','http://user:PRIVATE@127.0.0.1:8188','http://127.0.0.1:8188?PRIVATE'])assert.throws(()=>createLocalEntryHost({...input,apiOrigin}),{message:'local_entry_host_invalid'});
 for(const overrides of [{scriptId:'unsafe"'},{routes:['/']},{routes:['/api/a?secret']},{routes:[]},{publicConfig:{v:'x'.repeat(8192)}}])assert.throws(()=>createLocalEntryHost({...input,...overrides}),{message:'local_entry_host_invalid'});
});
async function serve(server){server.listen(0,'127.0.0.1');await once(server,'listening');return 'http://127.0.0.1:'+server.address().port;}
async function close(server){server.closeAllConnections();await new Promise(r=>server.close(r));}
test('local host routes only declared GET API paths, strips ambient credentials and returns private safe failures',async()=>{
 let calls=[];let status=200,body='{"status":"ok"}',type='application/json';
 const api=createServer((req,res)=>{calls.push({url:req.url,headers:req.headers});res.writeHead(status,{'Content-Type':type,'Set-Cookie':'PRIVATE=1','Location':'https://remote.invalid/PRIVATE'});res.end(body);});const apiOrigin=await serve(api);
 const host=createLocalEntryHost({...input,apiOrigin});let middleware;host.plugins[0].configureServer({middlewares:{use:fn=>middleware=fn}});const server=createServer((req,res)=>middleware(req,res,()=>{res.end('HTML');}));const origin=await serve(server);
 try{
  const result=await fetch(origin+'/api/v1/context',{headers:{Authorization:'Bearer synthetic',Cookie:'PRIVATE=1','X-Service-Key':'PRIVATE'}});assert.equal(result.status,200);assert.deepEqual(await result.json(),{status:'ok'});assert.equal(result.headers.get('cache-control'),'private, no-store');assert.equal(result.headers.get('set-cookie'),null);assert.equal(result.headers.get('location'),null);assert.equal(calls[0].headers.authorization,'Bearer synthetic');assert.equal(calls[0].headers.cookie,undefined);assert.equal(calls[0].headers['x-service-key'],undefined);
  for(const path of ['/api/private?token=PRIVATE','/api/v1/context/','/api/v1/context-extra']){const result=await fetch(origin+path);assert.equal(result.status,404);assert.equal(result.headers.get('cache-control'),'private, no-store');}
  const bodyStatus=await new Promise(resolve=>{const req=request(origin+'/api/v1/context',{method:'GET',headers:{'Content-Length':'1'}},res=>{res.resume();res.on('end',()=>resolve(res.statusCode));});req.end('x');});assert.equal(bodyStatus,422);assert.equal(calls.length,1);
  assert.equal(calls.length,1);const post=await fetch(origin+'/api/v1/context',{method:'POST',body:'PRIVATE'});assert.equal(post.status,405);assert.equal(calls.length,1);
  for(const scenario of ['redirect','oversized','wrong-type','malformed','truncated']){status=scenario==='redirect'?302:200;type=scenario==='wrong-type'?'text/html':'application/json';body=scenario==='oversized'?'x'.repeat(65537):scenario==='malformed'?'PRIVATE':scenario==='truncated'?'{':'{}';const response=await fetch(origin+'/api/v1/context');assert.equal(response.status,503);assert.equal((await response.json()).error_id,'authorization_unavailable');}
  await close(api);const unavailable=await fetch(origin+'/api/v1/context');assert.equal(unavailable.status,503);assert.ok(!(await unavailable.text()).includes('PRIVATE'));
 }finally{await close(server);if(api.listening)await close(api);}
});
test('resolved CLI overrides cannot expose the local host or replace routing policy',()=>{
 const host=createLocalEntryHost(input),plugin=host.plugins[0];
 for(const change of [{host:'0.0.0.0'},{host:true},{cors:true},{hmr:true},{strictPort:false},{proxy:{'/api':'http://remote.invalid'}}])assert.throws(()=>plugin.configResolved({...host,command:'serve',server:{...host.server,...change}}),{message:'local_entry_host_invalid'});
});
test('local host bounds a stalled response and closes its upstream after the deadline',async()=>{
 let closed=false;const api=createServer((req,res)=>{res.writeHead(200,{'Content-Type':'application/json'});res.write('{');res.once('close',()=>closed=true);});const apiOrigin=await serve(api);
 let middleware;createLocalEntryHost({...input,apiOrigin}).plugins[0].configureServer({middlewares:{use:fn=>middleware=fn}});const server=createServer((req,res)=>middleware(req,res,()=>res.end()));const origin=await serve(server);
 try{const start=Date.now(),response=await fetch(origin+'/api/v1/context');assert.equal(response.status,503);assert.equal((await response.json()).error_id,'authorization_unavailable');assert.ok(Date.now()-start>=11000&&Date.now()-start<14000);for(let i=0;i<100&&!closed;i++)await new Promise(r=>setTimeout(r,10));assert.equal(closed,true);}finally{await close(server);await close(api);}
});
